#!/usr/bin/env python3
"""Visor autocontenido de evidencias y PNG; NO es otra implementación de la app."""
from pathlib import Path
import argparse, base64, html, io, json, re
from PIL import Image
ROOT=Path(__file__).resolve().parents[2]
HERE=Path(__file__).resolve().parent
h=html.escape

def uri(path):
    mime='image/png' if path.suffix=='.png' else 'image/jpeg'
    return f'data:{mime};base64,'+base64.b64encode(path.read_bytes()).decode()

def asset_preview(path):
    # Lighter gallery only; original production PNGs remain unchanged in app assets.
    with Image.open(path) as image:
        image.thumbnail((1000,1000),Image.Resampling.LANCZOS)
        buffer=io.BytesIO();image.save(buffer,format='PNG',optimize=True)
    return 'data:image/png;base64,'+base64.b64encode(buffer.getvalue()).decode()

def frame(path,label,kind):
    meta=path.with_suffix('.json')
    info=json.loads(meta.read_text()) if meta.exists() else {}
    label=info.get('label',label)
    dims=f"{info.get('width','?')} × {info.get('height','?')} px"
    if info.get('logical_width') and info['logical_width']!=info.get('width'):
        dims+=f" · vista lógica {info['logical_width']} × {info['logical_height']} (reescalada)"
    landscape=info.get('width',0)>info.get('height',1)
    return f'''<figure class="capture {'wide' if landscape else ''}"><button class="open-image" aria-label="Ampliar {h(label)}"><img loading="lazy" src="{uri(path)}" alt="{h(label)}"></button><figcaption><strong>{h(label)}</strong><span>{h(kind)} · {dims}</span></figcaption></figure>'''

