rows=''.join(f'''<tr><td>{r['number']:02}</td><td><strong>{h(r['name'])}</strong><code>{h(r['requested_file'])}</code></td><td><span class="pill {'amber' if r['file'] else 'neutral'}">{h(r['status'])}</span></td><td>{h(r['evidence'])}<small>{h(r['remaining'])}</small></td></tr>''' for r in inventory)
